INSERT INTO delivery_tracking (deliveryId,courierId,latitude,longitude,accuracy,speed,heading,timestamp) SELECT id,courierId,pickupLatitude,pickupLongitude,12.0,34.0,90.0,DATE_SUB(NOW(), INTERVAL 15 MINUTE) FROM deliveries WHERE trackingCode LIKE 'QA260929-%' AND courierId IS NOT NULL AND status IN ('in-transit','assigned');
INSERT INTO delivery_reviews (deliveryId,reviewerUserId,score,comment) SELECT id,customerId,CASE MOD(id,3) WHEN 0 THEN 5 WHEN 1 THEN 4 ELSE 3 END,'QA synthetic review for delivery flow coverage' FROM deliveries WHERE trackingCode LIKE 'QA260929-%' AND status='delivered';
INSERT INTO notifications (userId,type,title,message,relatedDeliveryId,isRead) SELECT customerId,'delivery_status','QA parcel update',CONCAT('Synthetic QA update for ',trackingCode),id,false FROM deliveries WHERE trackingCode LIKE 'QA260929-%';
INSERT INTO notifications (userId,type,title,message,relatedDeliveryId,isRead) SELECT courierId,'delivery_assigned','QA route assignment',CONCAT('Synthetic QA parcel ',trackingCode,' is on your route.'),id,false FROM deliveries WHERE trackingCode LIKE 'QA260929-%' AND courierId IS NOT NULL;
INSERT INTO dispatch_runs (status,requestedBy,parcelCount,assignedCount,unassignedCount,aiSummary) SELECT 'committed',id,100,90,10,'QA_SEED_20260929 dispatch run: 90 courier assignments, 10 pending customer parcels.' FROM users WHERE role='admin' ORDER BY id LIMIT 1;
INSERT INTO dispatch_assignments (dispatchRunId,deliveryId,courierId,sequence,score,distanceToPickupKm,areaMatch,reasoning,status) SELECT @qa_dispatch_id,id,courierId,ROW_NUMBER() OVER (PARTITION BY courierId ORDER BY id),80 + MOD(id,20),4.5 + MOD(id,7),'Johannesburg–Pretoria QA corridor','QA synthetic SmartStack assignment; route fit and courier capacity reviewed.','assigned' FROM deliveries WHERE trackingCode LIKE 'QA260929-%' AND courierId IS NOT NULL;
INSERT INTO smart_match_audits (courierId,deliveryId,recommendationId,matchScore,routeCompatibilityScore,deadlineRisk,decision,routeConsidered,reason,outcomeNote) SELECT courierId,id,NULL,82 + MOD(id,16),78 + MOD(id,19),CASE WHEN status='delivered' THEN 'low' WHEN status='in-transit' THEN 'medium' ELSE 'high' END,CASE WHEN status='delivered' THEN 'completed' WHEN status='in-transit' THEN 'accepted' ELSE 'recommended' END,JSON_OBJECT('seed','QA_SEED_20260929','corridor','Johannesburg–Pretoria','capacityAware',true),'QA SmartMatch audit decision; QA_SEED_20260929',CASE WHEN status='delivered' THEN 'QA completed outcome' ELSE NULL END FROM deliveries WHERE trackingCode LIKE 'QA260929-%' AND courierId IS NOT NULL;
INSERT INTO delivery_runs (courierId,status,startedAt) SELECT (SELECT id FROM users WHERE openId='qa-seed-20260929-courier-01' LIMIT 1),'active',DATE_SUB(NOW(), INTERVAL 2 HOUR);
INSERT INTO delivery_run_stops (runId,deliveryId,sequence,status,courierAcceptedAt,courierArrivedAt,pickupCompletedAt,courierNote) SELECT (SELECT id FROM delivery_runs WHERE courierId=(SELECT id FROM users WHERE openId='qa-seed-20260929-courier-01' LIMIT 1) ORDER BY id DESC LIMIT 1),d.id,ROW_NUMBER() OVER (ORDER BY d.id),CASE WHEN d.status='delivered' THEN 'completed' WHEN d.status='in-transit' THEN 'navigating' ELSE 'queued' END,DATE_SUB(NOW(), INTERVAL 2 HOUR),CASE WHEN d.status IN ('in-transit','delivered') THEN DATE_SUB(NOW(), INTERVAL 90 MINUTE) ELSE NULL END,CASE WHEN d.status IN ('in-transit','delivered') THEN DATE_SUB(NOW(), INTERVAL 60 MINUTE) ELSE NULL END,'QA daily route stop; QA_SEED_20260929' FROM deliveries d WHERE d.trackingCode LIKE 'QA260929-%' AND d.courierId=(SELECT id FROM users WHERE openId='qa-seed-20260929-courier-01' LIMIT 1) AND d.status IN ('in-transit','assigned','delivered');
INSERT INTO delivery_runs (courierId,status,startedAt) SELECT (SELECT id FROM users WHERE openId='qa-seed-20260929-courier-02' LIMIT 1),'active',DATE_SUB(NOW(), INTERVAL 2 HOUR);
INSERT INTO delivery_run_stops (runId,deliveryId,sequence,status,courierAcceptedAt,courierArrivedAt,pickupCompletedAt,courierNote) SELECT (SELECT id FROM delivery_runs WHERE courierId=(SELECT id FROM users WHERE openId='qa-seed-20260929-courier-02' LIMIT 1) ORDER BY id DESC LIMIT 1),d.id,ROW_NUMBER() OVER (ORDER BY d.id),CASE WHEN d.status='delivered' THEN 'completed' WHEN d.status='in-transit' THEN 'navigating' ELSE 'queued' END,DATE_SUB(NOW(), INTERVAL 2 HOUR),CASE WHEN d.status IN ('in-transit','delivered') THEN DATE_SUB(NOW(), INTERVAL 90 MINUTE) ELSE NULL END,CASE WHEN d.status IN ('in-transit','delivered') THEN DATE_SUB(NOW(), INTERVAL 60 MINUTE) ELSE NULL END,'QA daily route stop; QA_SEED_20260929' FROM deliveries d WHERE d.trackingCode LIKE 'QA260929-%' AND d.courierId=(SELECT id FROM users WHERE openId='qa-seed-20260929-courier-02' LIMIT 1) AND d.status IN ('in-transit','assigned','delivered');
INSERT INTO delivery_runs (courierId,status,startedAt) SELECT (SELECT id FROM users WHERE openId='qa-seed-20260929-courier-03' LIMIT 1),'active',DATE_SUB(NOW(), INTERVAL 2 HOUR);
INSERT INTO delivery_run_stops (runId,deliveryId,sequence,status,courierAcceptedAt,courierArrivedAt,pickupCompletedAt,courierNote) SELECT (SELECT id FROM delivery_runs WHERE courierId=(SELECT id FROM users WHERE openId='qa-seed-20260929-courier-03' LIMIT 1) ORDER BY id DESC LIMIT 1),d.id,ROW_NUMBER() OVER (ORDER BY d.id),CASE WHEN d.status='delivered' THEN 'completed' WHEN d.status='in-transit' THEN 'navigating' ELSE 'queued' END,DATE_SUB(NOW(), INTERVAL 2 HOUR),CASE WHEN d.status IN ('in-transit','delivered') THEN DATE_SUB(NOW(), INTERVAL 90 MINUTE) ELSE NULL END,CASE WHEN d.status IN ('in-transit','delivered') THEN DATE_SUB(NOW(), INTERVAL 60 MINUTE) ELSE NULL END,'QA daily route stop; QA_SEED_20260929' FROM deliveries d WHERE d.trackingCode LIKE 'QA260929-%' AND d.courierId=(SELECT id FROM users WHERE openId='qa-seed-20260929-courier-03' LIMIT 1) AND d.status IN ('in-transit','assigned','delivered');
